import{_ as o,a0 as d,w as n,s as l,ao as i,I as s,a1 as r,A as a,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"小評磁盤分區軟件GParted 0.16.2 | LCTT x X-CMD","titleTemplate":false,"description":"小評磁盤分區軟件GParted 0.16.2 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"小評磁盤分區軟件GParted 0.16.2 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"小評磁盤分區軟件GParted 0.16.2 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/GParted 0.16.2 Review","title":"小評磁盤分區軟件GParted 0.16.2","tag":"201310","desc":""},"relativePath":"201310/GParted 0.16.2 Review.md","filePath":"[post].md"}'),m={name:"201310/GParted 0.16.2 Review.md"};function f(u,t,g,P,w,G){const p=d("Link");return n(),l("div",null,[t[13]||(t[13]=i('<h1 id="小評磁盤分區軟件gparted-0-16-2" tabindex="-1">小評磁盤分區軟件GParted 0.16.2 <a class="header-anchor" href="#小評磁盤分區軟件gparted-0-16-2" aria-label="Permalink to “小評磁盤分區軟件GParted 0.16.2”">​</a></h1><p><strong>GParted可能是Linux平台上最重要的應用程序之一了，並且它也是最有用最易識別的軟件之一。</strong></p><p><img src="http://i1-news.softpedia-static.com/images/news2/GParted-Review-387094-2.jpg" alt="img"></p><p>不能把GParted作為一個單獨的應用程序來討論。公平的説，它本是採用GTK+開發的GNU Parted的前端程序。但是由於開發人員做了許多工作，使得它的功能已經不僅僅只是給這個複雜而難用的軟件提供一個簡單的圖形界面了。</p><p>GParted項目啓動於2004年，自從那時起開發人員一直在不斷的完善它。這個過程是緩慢的，最新發布的版本號是0.16.2（該版本已經被我們點評過）。難以想像這個開發工作一下就持續了近十年。</p><p>用户會發現GParted不僅僅是一個工具，還有一個名叫GParted Live的Live操作系統，它無需安裝即可直接使用，它可以在任何帶有光驅或者USB接口的系統上直接運行，包括Mac操作系統。</p><p>很難想像在Linux世界中沒有這個工具會怎樣，但是我們也不得不説，它並不是完成這方面工作唯一工具。</p><p>###安裝</p><p>這是一項困難的工作。GParted的開發者們只提供最新版軟件的源代碼，這就意味着如果你想獲取最好的版本就不得不做一些編譯的工作。這真是個壞消息。</p><p>我們在Ubuntu 13.10（代號俏皮的蠑螈）上安裝了GParted，一切都很順利。官方庫所提供的最新版是0.16.1，這個版本應該可以滿足大多數用户的需求了。該版本與最新0.16.2版之間的區別並不明顯，只是在一些設置上有所改動。</p><p>我們假設你真的如飢似渴般想要最新的版本。首先，下載軟件包然後解壓它。</p><p>下載GParted 0.16.2：</p>',12)),s("ul",null,[s("li",null,[r(p,{href:"http://sourceforge.net/projects/gparted/files/gparted/gparted-0.16.2/gparted-0.16.2.tar.bz2/download"},{default:a(()=>[...t[0]||(t[0]=[e("gparted-0.16.2.tar.bz2",-1)])]),_:1}),t[1]||(t[1]=e("[sources] [1.80 MB]",-1))])]),t[14]||(t[14]=i(`<p>這並不是一個很大的軟件，編譯時間也不會太長。通常，用户只需要輸入下面的命令：</p><pre><code>./configure
make
sudo make install
</code></pre><p>問題是正如你和我這樣的普通人，並沒有安裝該軟件所依賴的所有軟件包。這意味着，當 ./configure命令顯示錯誤的時候，你不得不一個一個的去安裝這些軟件。</p><p>好消息是，Ubuntu用户有一個非常方便的命令，適用於所有在他們倉庫中的應用。在使用./configure之前，首先輸入如下命令：</p><pre><code>sudo apt-get build-dep gparted
</code></pre><p>這條命令會從倉庫中獲得所有必須的依賴軟件包，並將用户從複雜的一個一個安裝依賴庫的工作中解救出來。</p><p>###使用</p><p>像我以前説的，這是一個磁盤分區編輯器。這意味着你可以通過它的用户界面進行移動、重新分配分區大小、重新分區以及做任何你想要做的事。</p><p>用户也可以刪除分區，修復那些被其他系統損壞了的USB盤。你必須足夠的小心。如果你像我一樣安裝了多系統，你會發現它會很容易損壞已經安裝了的Windows系統。</p><p>GParted能夠修改以下文件系統：btrfs, crypt / LUKS, ext2, ext3, ext4, fat16, fat32, hfs, hfs+, linux-swap, lvm2 pv, nilfs2, ntfs, reiserfs, reiser4, ufs, 以及 xfs。GParted也可以被用於克隆整個分區。</p><p>此外，GParted也得到了UEFI安全啓動的支持，能夠在任何具有此功能的PC電腦上流暢運行。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/GParted-Review-387094-2.jpg" alt=""></p><p><img src="http://i1-news.softpedia-static.com/images/news2/GParted-Review-387094-3.jpg" alt=""></p><p><img src="http://i1-news.softpedia-static.com/images/news2/GParted-Review-387094-5.jpg" alt=""></p><p><img src="http://i1-news.softpedia-static.com/images/news2/GParted-Review-387094-6.jpg" alt=""></p><p>###總結</p><p>誰會知道修改分區是件有趣的事呢？GParted把這項枯燥又具有潛在危險的活動變得並不那樣可怕，為用户提供了一個很棒的用户體驗，而不像命令列的應用程序那樣。</p><p>那些用户不得不在終端中調整分區的日子已經遠去了。GParted看起來像一個專業的解決方案，它是我們不能沒有的工具。</p><p><strong>優點</strong></p><p>使用其它操作系統的用户，比如windows或者Mac，需要支付高額的費用來使用這一類軟件。而Linux用户則可以免費獲得，而且開發者在不斷的維護這個程序。</p><p>它的用户界面非常整潔，簡單易懂，甚至Linux新手都能看的明白。</p><p><strong>不足</strong></p><p>使用這個程序會很容易的把事情搞壞。尤其是一但具有了root用户的權限，它會具有潛在的破壞性。</p><p>對於這種情況，如果GParted能夠提供更多綜合性的建議，或者在開始的時候僅提供一個初級版本的話，或許會更合適。</p><hr>`,25)),s("p",null,[t[3]||(t[3]=e("via: ",-1)),r(p,{href:"http://www.softpedia.com/reviews/linux/GParted-Review-387094.shtml"},{default:a(()=>[...t[2]||(t[2]=[e("http://www.softpedia.com/reviews/linux/GParted-Review-387094.shtml",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=e("本文由 ",-1)),r(p,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[4]||(t[4]=[e("LCTT",-1)])]),_:1}),t[7]||(t[7]=e(" 原創翻譯，",-1)),r(p,{href:"http://linux.cn/"},{default:a(()=>[...t[5]||(t[5]=[e("Linux中國",-1)])]),_:1}),t[8]||(t[8]=e(" 榮譽推出",-1))]),s("p",null,[t[11]||(t[11]=e("譯者：",-1)),r(p,{href:"https://github.com/woodboow"},{default:a(()=>[...t[9]||(t[9]=[e("woodboow",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),r(p,{href:"https://github.com/carolinewuyan"},{default:a(()=>[...t[10]||(t[10]=[e("Caroline",-1)])]),_:1})])])}const C=o(m,[["render",f]]);export{v as __pageData,C as default};
